SELECT product_id, warehouse_id, position_id, quantity
FROM inventory
WHERE product_id = #{productId}

SELECT product_id, warehouse_id, position_id, quantity
FROM inventory
WHERE product_id = #{productId} AND warehouse_id = #{warehouseId}

SELECT product_id, warehouse_id, position_id, quantity
FROM inventory
WHERE product_id = #{productId}
  AND warehouse_id = #{warehouseId}
  AND (position_id = #{positionId} OR (#{positionId} IS NULL AND position_id IS NULL))

mapper.update:
UPDATE inventory SET quantity = #{quantity}
WHERE product_id = #{productId}
  AND warehouse_id = #{warehouseId}
  AND (position_id = #{positionId} OR (#{positionId} IS NULL AND position_id IS NULL))
